package com.agacostays.billing.mapper; import com.agacostays.billing.entity.Bill;import com.agacostays.billing.dto.response.FinalBillResponse;import org.springframework.stereotype.Component; @Component public class BillMapper{public FinalBillResponse toResponse(Bill b){return new FinalBillResponse(b.getBillId(),b.getBranchId(),b.getBookingId(),b.getCustomerId(),b.getRoomCharges(),b.getRestaurantCharges(),b.getTaxAmount(),b.getDiscount(),b.getFinalAmount(),b.getBillStatus().name(),b.getBillType().name(),b.getPaymentStatus(),b.getInvoiceUrl(),b.getCreatedAt(),b.getUpdatedAt());}}
